import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls} from './pathways-views.js?v=20261031-entry1';
import {quantumCurveSVG} from './quantum-plots.js?v=20261031-entry1';
export {esc,num,table,notes,sources,readControls};
const val=x=>typeof x==='boolean'?(x?'是':'否'):typeof x==='number'?num(x):x==null?'未提供':typeof x==='object'?JSON.stringify(x):String(x);
const labels={exchangeSides:'交换上下两侧',fourfold:'保留四重旋转',inversion:'空间反演',chiral:'几何手性',polar:'允许极向量',Rx:'绕 x 的 π 旋转',Rz:'绕 z 的 π 旋转',T:'时间反演'};
const anchors=new Map(),clean=r=>{const c=structuredClone(r);delete c.learningEvidence;return c;};
export const controlsHTML=(m,v)=>baseControls({...m,fields:m.fields.map(f=>f.type==='number'&&!['sites','layers','cut'].includes(f.key)?{...f,step:'any'}:f)},v).replace(/(<label[^>]*>)([^<]*)(?=<(?:select|input))/g,'$1<span>$2</span>');
function project(p,yaw=35,pitch=24){const a=yaw*Math.PI/180,b=pitch*Math.PI/180;return [p[0]*Math.cos(a)-p[1]*Math.sin(a),p[2]*Math.cos(b)+(p[0]*Math.sin(a)+p[1]*Math.cos(a))*Math.sin(b)];}
export function geometrySVG(g,{yaw=35,pitch=24,points=g.points,title='原结构',ghost=null}={}){
 const combined=[...points,...(ghost||[])],q=combined.map(p=>project(p,yaw,pitch)),max=Math.max(1,...q.flat().map(Math.abs)),scale=145/max,xy=p=>{const a=project(p,yaw,pitch);return [270+a[0]*scale,190-a[1]*scale];};
 const palette=['#267764','#bf8142','#7266a8','#b85959'],unique=[...new Set(g.labels)],color=i=>palette[unique.indexOf(g.labels[i])%palette.length];
 return `<svg viewBox="0 0 540 410" role="img" aria-label="${esc(title)}的三维投影"><text x="20" y="28">${esc(title)}</text>${ghost?ghost.map(p=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="8" fill="none" stroke="#a3afa8" stroke-width="2"/>`;}).join(''):''}${points.map((p,i)=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="7" fill="${color(i)}"><title>${esc(g.labels[i])} · ${p.map(num).join(', ')}</title></circle>`;}).join('')}${[[1,0,0],[0,1,0],[0,0,1]].map((p,i)=>{const [x,y]=project(p,yaw,pitch);return `<line x1="65" y1="345" x2="${65+38*x}" y2="${345-38*y}" stroke="#4f6559"/><text x="${65+48*x}" y="${345-48*y}">${['x','y','z'][i]}</text>`;}).join('')}<text x="20" y="395">${esc(unique.join(' / '))} · 拖动下方视角滑块</text></svg>`;
}
function vectorSVG(title,a,b){const scale=90/Math.max(1,...a.map(Math.abs),...b.map(Math.abs));const coords=v=>{const q=project(v);return[135+scale*q[0],120-scale*q[1]];};return `<svg viewBox="0 0 270 260" role="img" aria-label="${esc(title)}变换前后"><text x="20" y="25">${esc(title)}</text><path d="M30 120H240M135 45V205" stroke="#d4dfd6"/>${[a,b].map((v,i)=>{const [x,y]=coords(v);return `<line x1="135" y1="120" x2="${x}" y2="${y}" stroke="${i?'#b87631':'#267764'}" stroke-width="${i?3:5}"/><circle cx="${x}" cy="${y}" r="5" fill="${i?'#b87631':'#267764'}"/>`;}).join('')}<text x="15" y="230">绿：原向量　金：变换后</text></svg>`;}
const matrix=m=>table(m[0].map((_,i)=>'第 '+(i+1)+' 列'),m.map(row=>row.map(num)));
export function resultHTML(module,r){
 const inverse=r.inverseSetup;
 return `<div class="cn-summary">${table(['本次结果','数值 / 诊断'],r.summary.map(s=>[s.label,val(s.value)]))}</div><section class="ct-panel"><h3>结构与操作三维演示</h3><div class="ft-pair"><div id="ft-geometry"></div><div id="ft-transformed"></div></div><div class="cn-audit-controls"><label>方位角<input type="range" id="ft-yaw" min="0" max="360" value="35"></label><label>仰角<input type="range" id="ft-pitch" min="-70" max="70" value="24"></label></div><p>${module==='chirality'?'左：原构型；右：镜像经最佳正旋转配准后的点集，灰圈为原构型。元素对应保存在完整 JSON。':'灰圈为原构型，右侧可应用所选空间操作；表面图重复显示 3×3 个面内原胞。自旋链图仅示意位点排列。'}</p></section>
 <section class="ct-panel"><h3>实空间—动量空间—自旋联动</h3><p>选择本次模型提供的操作，分别变换位置、波矢和轴矢量自旋。下方是独立向量演示；不替代上方完整模型的对称性检验。</p><label>空间操作<select id="ft-operation" aria-label="空间操作">${r.operations.map((o,i)=>`<option value="${i}">${i+1} · ${esc(o.name||('det(R)='+o.determinant+(o.flipsNormal?' · 交换两侧':'')))}</option>`).join('')}</select></label><label>叠加时间反演<select id="ft-time" aria-label="叠加时间反演"><option value="no">否</option><option value="yes">是</option></select></label><details><summary>调整三个输入向量</summary><div class="ft-vectors">${[['position','位置 r',[.3,.2,.1]],['momentum','波矢 k（弧度/长度）',[.4,.3,.2]],['spin','自旋 S',[.2,.4,.7]]].map(([key,title,v])=>`<fieldset><legend>${title}</legend>${v.map((x,i)=>`<label>${['x','y','z'][i]}<input id="ft-${key}-${i}" type="number" min="-10" max="10" step="any" value="${x}"></label>`).join('')}</fieldset>`).join('')}</div></details><div id="ft-matrix"></div><button id="ft-link" type="button" class="secondary">应用操作并联动</button><div id="ft-linked-result" role="status"></div></section>
 ${r.pseudo?`<section class="ct-panel"><h3>容差与伪对称性证据</h3><p>候选来自未扰动母构型；每项按固定原子对应检查最大位移。当前接受集合${r.pseudo.closed?'通过':'未通过'}闭合检查。</p>${table(['操作序号','最大映射距离','当前容差接受'],r.pseudo.residuals.map(a=>[a.index+1,num(a.maximum),val(a.accepted)]))}<p>严格当前构型的操作数与近似候选数已分别列在顶部。</p></section>`:''}
 ${r.spectrum?`<section class="ct-panel"><h3>保护条件与量子态</h3>${table(['操作','Hamiltonian 相对残差','本次数值保持'],Object.entries(r.spectrum.symmetry).map(([k,v])=>[labels[k],num(v),v<1e-8?'是':'否']))}<p>${esc(r.spectrum.stateSelection)}</p><p>本征态残差：${num(r.spectrum.stateResidual)}</p><h4>AKLT 固定点的虚拟自旋</h4><div class="ft-pair">${matrix(r.virtual.Ux)}${matrix(r.virtual.Uz)}</div><p>${esc(r.virtual.explanation)} 当前${r.virtual.available?'处于 AKLT 点，解析交换相位为 −1':'为扰动态，不输出虚拟射影类别'}。</p></section>`:''}
 ${r.optical?`<section class="ct-panel"><h3>独立往返偏振实验</h3><p>旋转角来自你指定的教学参数，未由当前结构拟合。固定实验室 x/y 轴，回程采用${r.optical.model==='natural'?'相反旋转':'同向旋转'}。</p><div class="ft-pair"><div><h4>去程矩阵</h4>${matrix(r.optical.forward)}</div><div><h4>往返总矩阵</h4>${matrix(r.optical.roundTrip)}</div></div><p>输入 x 线偏振后的输出：${r.optical.output.map(num).join(', ')}</p></section>`:''}
 ${r.plots.map(p=>`<section class="ct-panel"><h3>${esc(p.title)}</h3>${quantumCurveSVG(p.series,{xLabel:p.xLabel,yLabel:p.yLabel})}</section>`).join('')}
 <section class="ct-panel"><h3>扰动路径追踪</h3><p>逐点检查参数、对称性与诊断；本页只计算已列出的采样点。</p><label>路径采样点<input id="ft-path" type="range" min="0" max="${r.path.length-1}" value="0" step="1"></label><div id="ft-path-result"></div><button id="ft-load-path" type="button" class="secondary">将此路径点载入主实验</button></section>
 <section class="ct-panel"><h3>推导与操作回放</h3><label>查看步骤<input id="ft-frame" type="range" min="0" max="${r.replay.length-1}" value="0" step="1"></label><div id="ft-frame-result"></div></section>
 <section class="ct-panel"><h3>逆向对称性鉴别</h3><p>选择未知样本，每次增加一项检验，勾选全部仍可能的候选。答案可以不唯一；只在本题候选集合内判断。</p><label>未知样本<select id="ft-sample">${inverse.candidates.map((c,i)=>`<option value="${c.id}">样本 ${i+1}</option>`).join('')}</select></label><label>下一项检验<select id="ft-measure">${inverse.measurements.map(k=>`<option value="${k}">${labels[k]||k}</option>`).join('')}</select></label><button id="ft-observe" type="button" class="secondary">获得这项检验证据</button><div id="ft-observations" role="status">尚未获得证据，所有候选都需要保留。</div><fieldset><legend>仍可能的候选（可多选）</legend>${inverse.candidates.map(c=>`<label class="ft-check"><input type="checkbox" data-ft-candidate="${c.id}" checked> ${esc(c.title)}</label>`).join('')}</fieldset><button id="ft-inverse-grade" type="button" class="secondary">检查候选集合</button><div id="ft-inverse-result" role="status"></div></section>
 <section class="ct-panel"><h3>公式与适用条件</h3>${r.formulas.map(f=>`<div class="obs-formula">${esc(f)}</div>`).join('')}${notes(r.assumptions)}</section>
 <section class="ct-panel"><h3>成对实验与研究证据</h3><button id="ft-pin" type="button" class="secondary">固定本次结果为 A</button><button id="ft-compare" type="button" class="secondary">比较当前 B 并保存</button><button id="ft-clear" type="button" class="secondary">清除 A</button><label>对照解释<textarea id="ft-explanation" rows="3" maxlength="6000"></textarea></label><div id="ft-comparison" role="status"></div></section>`;
}
export function bindResult(module,r,root,{runLinked,runInverse,input,isCurrent,onEvidence}){
 const $=s=>root.querySelector(s);let active=true,linkTicket=0,inverseTicket=0,revealed=[];
 const valid=()=>active&&isCurrent();
 const selected=()=>r.operations[Number($('#ft-operation').value)];
 function drawGeometry(){if(!valid())return;const opt={yaw:Number($('#ft-yaw').value),pitch:Number($('#ft-pitch').value)},o=selected();$('#ft-geometry').innerHTML=geometrySVG(r.geometry,opt);const points=module==='chirality'?r.geometry.aligned:r.geometry.points.map(p=>o.matrix.map((row,i)=>row.reduce((s,v,j)=>s+v*p[j],o.translation[i])));$('#ft-transformed').innerHTML=geometrySVG(r.geometry,{...opt,points,ghost:r.geometry.points,title:module==='chirality'?'镜像最佳正旋转配准':'所选空间操作后的结构'});$('#ft-matrix').innerHTML=matrix(o.matrix)+`<p>平移 t：${o.translation.map(num).join(', ')}</p>`;}
 $('#ft-yaw').oninput=drawGeometry;$('#ft-pitch').oninput=drawGeometry;drawGeometry();
 const clearLinked=()=>{linkTicket++;onEvidence('linked',null);$('#ft-linked-result').textContent='向量或操作已改变，请应用操作。';$('#ft-link').disabled=false;};
 $('#ft-operation').onchange=()=>{clearLinked();drawGeometry();};$('#ft-time').onchange=clearLinked;
 for(const key of ['position','momentum','spin'])for(let i=0;i<3;i++)$('#ft-'+key+'-'+i).oninput=clearLinked;
 $('#ft-link').onclick=async()=>{if(!valid())return;const id=++linkTicket,o=selected(),payload={matrix:o.matrix,translation:o.translation,timeReversal:$('#ft-time').value==='yes'};for(const key of ['position','momentum','spin'])payload[key]=[0,1,2].map(i=>($('#ft-'+key+'-'+i).value.trim()===''?NaN:Number($('#ft-'+key+'-'+i).value)));$('#ft-link').disabled=true;try{if(['position','momentum','spin'].some(key=>payload[key].some(x=>!Number.isFinite(x))))throw new Error('请完整填写三个向量的有限数值。');const answer=await runLinked(payload);if(!valid()||id!==linkTicket)return;$('#ft-linked-result').innerHTML=`<div class="ft-vectors">${vectorSVG('实空间位置',payload.position,answer.real)}${vectorSVG('波矢',payload.momentum,answer.momentum)}${vectorSVG('自旋（轴矢量）',payload.spin,answer.spin)}</div>`+table(['对象','变换前','变换后'],[['r',payload.position.map(num).join(', '),answer.real.map(num).join(', ')],['k',payload.momentum.map(num).join(', '),answer.momentum.map(num).join(', ')],['S',payload.spin.map(num).join(', '),answer.spin.map(num).join(', ')]] )+`<p>${esc(answer.convention)}</p><p>平移相位（实部、虚部）：${answer.phase.map(num).join(', ')}</p>`;onEvidence('linked',{input:payload,result:answer});}catch(e){if(valid()&&id===linkTicket)$('#ft-linked-result').textContent=e.message;}finally{if(valid()&&id===linkTicket)$('#ft-link').disabled=false;}};
 const frame=()=>{if(!valid())return;const f=r.replay[Number($('#ft-frame').value)];$('#ft-frame-result').innerHTML=`<h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>`;};$('#ft-frame').oninput=frame;frame();
 const path=()=>{if(!valid())return;const p=r.path[Number($('#ft-path').value)];const plain=Object.entries(p).filter(([k])=>k!=='symmetry'&&k!=='energies');$('#ft-path-result').innerHTML=table(['诊断','数值'],plain.map(([k,v])=>[{parameter:'参数值',order:'保留操作数',closed:'闭合',normalFlips:'交换两侧操作数',accepted:'容差接受数',groundMultiplicity:'基态空间维数',firstSpacing:'最低两级间距',gapAboveGroundSpace:'基态空间上方能隙'}[k]||k,val(v)]))+(p.symmetry?table(['保护操作','相对残差','数值保持'],Object.entries(p.symmetry).map(([k,v])=>[labels[k],num(v),v<1e-8?'是':'否'])):'');onEvidence('path',{index:Number($('#ft-path').value),point:structuredClone(p),input:structuredClone(input)});};$('#ft-path').oninput=path;path();
 $('#ft-load-path').onclick=()=>{if(!valid())return;const value=r.path[Number($('#ft-path').value)].parameter,key=module==='layers'?'registry':module==='chirality'?'tolerance':input.pathAxis,el=$('#pw-'+key);el.value=String(value);$('#pw-form').oninput({target:el});$('#pw-form').onsubmit({preventDefault(){}});};
 const inverseInvalidate=()=>{inverseTicket++;$('#ft-observe').disabled=false;$('#ft-inverse-grade').disabled=false;$('#ft-inverse-result').textContent='选择已改变，请重新检查。';onEvidence('inverse',null);};
 $('#ft-sample').onchange=()=>{revealed=[];inverseInvalidate();$('#ft-observations').textContent='新样本尚无证据；保留全部候选后逐项鉴别。';root.querySelectorAll('[data-ft-candidate]').forEach(c=>c.checked=true);};
 root.querySelectorAll('[data-ft-candidate]').forEach(c=>c.onchange=inverseInvalidate);
 async function inspect(grade){if(!valid())return;const id=++inverseTicket;if(!grade&&!revealed.includes($('#ft-measure').value))revealed.push($('#ft-measure').value);const payload={domain:r.inverseDomain,target:$('#ft-sample').value,revealed:[...revealed],guesses:[...root.querySelectorAll('[data-ft-candidate]')].filter(c=>c.checked).map(c=>c.dataset.ftCandidate),grade};$('#ft-observe').disabled=true;$('#ft-inverse-grade').disabled=true;try{const answer=await runInverse(payload);if(!valid()||id!==inverseTicket)return;$('#ft-observations').innerHTML=table(['已获得的检验','结果'],Object.entries(answer.observations).map(([k,v])=>[labels[k],val(v)]))+`<p>${answer.nextMeasurement?'建议下一项：'+esc(labels[answer.nextMeasurement]):answer.unique?'现有证据在本题候选中足以区分。':'剩余可用检验不能唯一地区分候选。'}</p>`;$('#ft-inverse-result').textContent=grade?(answer.correct?'✓ 候选集合正确；':'候选集合需要修正；')+'仍相容：'+answer.remaining.map(k=>answer.candidates.find(c=>c.id===k).title).join('、'):'证据已更新，请重新选择仍可能的候选。';onEvidence('inverse',grade?{input:payload,result:answer}:null);}catch(e){if(valid()&&id===inverseTicket)$('#ft-inverse-result').textContent=e.message;}finally{if(valid()&&id===inverseTicket){$('#ft-observe').disabled=false;$('#ft-inverse-grade').disabled=false;}}}
 $('#ft-observe').onclick=()=>inspect(false);$('#ft-inverse-grade').onclick=()=>inspect(true);
 const status=()=>{$('#ft-comparison').textContent=anchors.has(module)?'A 已固定；修改参数并计算 B 后可以比较。':'尚未固定 A。';};status();
 $('#ft-pin').onclick=()=>{if(!valid())return;anchors.set(module,{input:structuredClone(input),result:clean(r),created:new Date().toISOString()});onEvidence('comparison',null);status();};
 $('#ft-clear').onclick=()=>{anchors.delete(module);onEvidence('comparison',null);status();};
 $('#ft-explanation').oninput=()=>{onEvidence('comparison',null);$('#ft-comparison').textContent='解释已修改，请重新保存比较。';};
 $('#ft-compare').onclick=()=>{if(!valid())return;const A=anchors.get(module);if(!A){status();return;}const B={input:structuredClone(input),result:clean(r),created:new Date().toISOString()},explanation=$('#ft-explanation').value;onEvidence('comparison',{A,B,explanation});$('#ft-comparison').innerHTML=table(['量','A','B'],r.summary.map(s=>[s.label,val(A.result.summary.find(x=>x.label===s.label)?.value),val(s.value)]))+'<p>完整输入、结果与解释已附入本次计算，可导出或收录到材料项目。</p>';};
 return()=>{active=false;linkTicket++;inverseTicket++;};
}
